#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    // Поменяйте значения a и b местами.

    printf("%d %d\n", a, b);
    return 0;
}

exercise.referenceSolution:
#include <stdio.h>

int main(void) {
    int a, b;
    scanf("%d %d", &a, &b);
    int tmp = a;
    a = b;
    b = tmp;
    printf("%d %d\n", a, b);
    return 0;
}

